class Solution {
    public int maxProfit(int[] prices) {
        int hold = -prices[0];
        int sold = 0;
        int rest = 0;

        for (int day = 1; day < prices.length; day++) {
            int previousHold = hold;
            int previousSold = sold;
            int previousRest = rest;

            hold = Math.max(previousHold, previousRest - prices[day]);
            sold = previousHold + prices[day];
            rest = Math.max(previousRest, previousSold);
        }
        return Math.max(sold, rest);
    }
}

class Solution {
    public int maxProfit(int[] prices) {
        int n = prices.length;
        int[] hold = new int[n];
        int[] sold = new int[n];
        int[] rest = new int[n];

        hold[0] = -prices[0];
        sold[0] = Integer.MIN_VALUE / 4;
        rest[0] = 0;

        for (int day = 1; day < n; day++) {
            hold[day] = Math.max(hold[day - 1], rest[day - 1] - prices[day]);
            sold[day] = hold[day - 1] + prices[day];
            rest[day] = Math.max(rest[day - 1], sold[day - 1]);
        }
        return Math.max(sold[n - 1], rest[n - 1]);
    }
}

class Solution {
    public int maxProfit(int[] prices) {
        int[][] memo = new int[prices.length][2];
        for (int[] row : memo) {
            java.util.Arrays.fill(row, Integer.MIN_VALUE);
        }
        return dfs(prices, 0, 0, memo);
    }

    private int dfs(int[] prices, int day, int holding, int[][] memo) {
        if (day >= prices.length) {
            return 0;
        }
        if (memo[day][holding] != Integer.MIN_VALUE) {
            return memo[day][holding];
        }

        int best;
        if (holding == 1) {
            int sell = prices[day] + dfs(prices, day + 2, 0, memo);
            int keep = dfs(prices, day + 1, 1, memo);
            best = Math.max(sell, keep);
        } else {
            int buy = -prices[day] + dfs(prices, day + 1, 1, memo);
            int skip = dfs(prices, day + 1, 0, memo);
            best = Math.max(buy, skip);
        }
        memo[day][holding] = best;
        return best;
    }
}

class Solution {
    public int maxProfit(int[] prices) {
        int n = prices.length;
        int[] hold = new int[n];
        int[] cash = new int[n];
        hold[0] = -prices[0];

        for (int day = 1; day < n; day++) {
            int cooledCash = day >= 2 ? cash[day - 2] : 0;
            hold[day] = Math.max(hold[day - 1], cooledCash - prices[day]);
            cash[day] = Math.max(cash[day - 1], hold[day - 1] + prices[day]);
        }
        return cash[n - 1];
    }
}

class Solution {
    public int maxProfit(int[] prices) {
        int n = prices.length;
        int[] free = new int[n + 2];
        int[] holding = new int[n + 2];

        for (int day = n - 1; day >= 0; day--) {
            free[day] = Math.max(free[day + 1], -prices[day] + holding[day + 1]);
            holding[day] = Math.max(holding[day + 1], prices[day] + free[day + 2]);
        }
        return free[0];
    }
}
